package util

// Header-comment markers that prefix every generated file. The leading
// word distinguishes the two flavors a reader will encounter:
//
//   - "boilerplate" — fully generated and rewritten on every regen; never
//     edit by hand.
//   - "scaffolding" — generated once as a starting point, then owned and
//     edited by humans; the generator skips these on regen.
const (
	HeaderCommentGenNoEdit = "boilerplate generated by 'threeport-sdk gen' - do not edit"
	HeaderCommentGenMod    = "scaffolding generated by 'threeport-sdk gen' but will not be regenerated - intended for modification"
)
